package ioc; import core.Severity;import java.util.Objects; public final class Ioc{private final IocType type;private final String value;private final Severity severity;private final double confidence;private final String source;public Ioc(IocType type,String value,Severity severity,double confidence,String source){this.type=type==null?IocType.UNKNOWN:type;this.value=value==null?"":value;this.severity=severity==null?Severity.INFO:severity;this.confidence=Math.max(0,Math.min(1,confidence));this.source=source==null?"local":source;}public IocType type(){return type;}public String value(){return value;}public Severity severity(){return severity;}public double confidence(){return confidence;}public String source(){return source;}public boolean equals(Object o){return o instanceof Ioc&&((Ioc)o).type==type&&Objects.equals(((Ioc)o).value,value);}public int hashCode(){return Objects.hash(type,value);}public String toString(){return type+":"+value+":"+severity+":"+confidence;}}
